      model: "Kubernetes — распределённая база данных желаемого состояния плюс армия независимых контроллеров: каждый объект хранит spec (обещание) и status (отчёт), а бесконечный reconciliation loop сокращает разрыв между ними. Всё поведение системы предсказывается вопросом «кто и по какому watch сокращает какой разрыв».",
