        "Блочный диск с ReadWriteOnce нельзя примонтировать к нескольким репликам Deployment одновременно — это граница хранилища, а не ошибка конфигурации.",
        "Kubernetes не делает приложение отказоустойчивым: необработанный SIGTERM, состояние в памяти и потеря данных при внезапном завершении остаются ответственностью разработчика."
