    concepts: [],
    practicePrompt: "Возьмите один синхронный сдвиг (пару одновременных открытий или общий настрой в науке и искусстве) и объясните его дважды: как «созревшую проблему» в духе Мертона — через доступные инструменты, накопленные вопросы и сформированные ожидания, — и как «единый шаг духа» в духе Гегеля; затем приложите попперовский тест: какой факт заставил бы каждое из объяснений сдаться, и какое из них совместимо с чем угодно.",
    checkPrompt: "Не подглядывая, объясните: почему фаустовское возражение герменевтика не опровергает, а переворачивает; чем эпистема Фуко не гегелевский дух (анонимность, разрывы вместо ступеней, отсутствие телеологии); что такое несвоевременность Ницше и современник Агамбена; чем «структура чувства» Уильямса отличается от господствующей идеологии; в чём разница трёх режимов духа времени — этикетки, эмерджентной структуры и метафизического субъекта; что делают множественные открытия минимальным эмпирическим основанием понятия.",
    tier: 1,
