      problem: "«Дух времени» звучит как объяснение, но обычно это лишь атмосфера: не видно, чем понятие отличается от моды и мнения большинства, можно ли сохранить единство эпохи без гегелевского субъекта истории и что ответить Попперу, который считает концепт нефальсифицируемой псевдосущностью.",
