      mechanics: "Генеалогия: Гердер историзует разум — у каждой культуры свой центр тяжести. Гегель делает эпоху единством, объясняющим синхронные параллели (хитрость разума), но доступным лишь ретроспективно — сова Минервы. Маркс сохраняет холизм, меняя основание: господствующие идеи суть идеи господствующего класса, дух становится идеологией для разоблачения. Ницше превращает понятие в нормативную проблему несвоевременности — до Агамбена. Дильтей и Гадамер делают дух средой понимания (действенная история, слияние горизонтов). Хайдеггер, Фуко и Кун дают дух без субъекта (история бытия, эпистема с разрывами, парадигма). Блох, Козеллек, Беньямин, Деррида и Фишер расщепляют единство эпохи на несовпадающие времена. Поппер и Гомбрих требуют фальсифицируемости и каналов передачи вместо единого источника; эмпирика (множественные открытия, культуромика, меметика) даёт дефляционный смысл: совокупность инструментов и ожиданий, делающая мысли вероятными.",
