      model: "Ключевое свойство монолита — единица развёртывания, а не внутренняя структура; микросервисы — независимое развёртывание сервисов по бизнес-возможностям с собственными данными. Выбор — управление компромиссами во времени: организационные, технические и экономические силы двигают систему по спектру в обе стороны.",
      mechanics: "Закон Конвея: система воспроизводит структуру коммуникаций — микросервисы покупают организационную параллельность сотен команд («две пиццы», обратный манёвр Конвея), которую маленькая команда не оплатит. Цена распределённости: саги вместо двухфазного коммита, согласованность в конечном счёте как следствие CAP, усиление хвостовых задержек, распределённая трассировка вместо отладчика. Данные: каждому сервису своя база (иначе распределённый монолит); синхронные запросы, локальные копии через события, CQRS; ограниченные контексты DDD как естественные границы. Модульный монолит (Shopify, «величественный монолит») даёт границы без операционной цены. Коммуникация: REST/gRPC создаёт временную связанность (таймауты, circuit breakers, bulkheads), брокеры разрывают её (идемпотентность, transactional outbox). «Микросервисная премия» и правило «сначала монолит»; переход через strangler fig.",
