        "Нарезать сервисы по техническим слоям или слишком мелко (наносервисы): получается распределённый монолит — все издержки сети, никакой изоляции.",
        "Разделять данные между сервисами: общие таблицы связывают сильнее интерфейсов; изменение схемы одним ломает другого.",
        "Проводить границы до понимания домена: перенос границ через сеть и разные базы — месяцы, а не часы; отсюда «сначала монолит».",
        "Считать сагу откатом: компенсирующее действие — новая операция, а система может жить в промежуточном состоянии.",
