      model: "Кэш — копия дорогих данных у быстрого уровня; окупается только при неравномерном доступе и доминировании чтения. Главная сложность не в хранении, а в том, когда копия перестала быть правдой: TTL, вытеснение и инвалидация управляют временем и вероятностью расхождения с оригиналом.",
      mechanics: "Cache-aside: чтение через промах в базу с записью под TTL, запись обновляет базу и удаляет ключ — удаление инвариантно к порядку, обновление гонками сохраняет устаревшее. Истечение: ленивое удаление на доступе плюс активный цикл (10 раз/сек, выборка 20, повтор при >25% протухших, active-expire-effort с 6.0) — TTL гарантия невидимости, не физического удаления. Вытеснение: maxmemory + политика; LRU приближённый — 24-битная метка, выборка maxmemory-samples=5 в пул из 16; LFU — 16 бит времени + 8-битный логарифмический счётчик (255 ≈ миллион обращений), затухание lfu-decay-time. Гонка читателя и писателя лечится коротким TTL, отложенным двойным удалением, лизами (Facebook) или CDC (Debezium упорядочивает инвалидацию относительно коммитов); зависимости — тегами или версионированными ключами. Патологии: пробивание (несуществующие данные — негативное кэширование, фильтр Блума), лавина (одновременный TTL — jitter 10–20%, circuit breakers), прорыв (горячий ключ — лок SET NX PX, раздельные TTL, вероятностное XFetch-обновление без координации). Память: 50–90 байт оверхеда на ключ, listpack-хеши до 512 полей/64 байт, MessagePack вместо JSON, замер MEMORY USAGE и mem_fragmentation_ratio > 1.5 → активная дефрагментация. Топология: асинхронная репликация, Sentinel, Cluster 16384 слота CRC16 c хеш-тегами для мультиключевых команд, pipelining и Lua. CLIENT TRACKING (RESP3 push) даёт серверную инвалидацию локальных кэшей.",
