    practicePrompt: "Прослушайте good kid, m.A.A.d city от начала до конца с текстами и разберите рамку: где открывается и закрывается «молитва грешника» и что сообщает сама структура, чего нет ни в одной отдельной строчке. Затем возьмите пару u/i на To Pimp a Butterfly и опишите, как голос (тембр, срыв, пьянство) несёт смысл без перевода. Наконец, проследите механику удержания и раскрытия на одном альбоме — где ключ выдаётся не сразу и когда происходит сборка целого. Ничего не воспроизводилось в среде — проверяйте на записях.",
