    summary: "An English essay-lesson on Go from first principles to the edges of the runtime: the temperament — designed at Google ~2007 by Griesemer, Pike and Thompson for huge codebases, slow C++ builds and multicore servers, valuing readability over expressiveness, orthogonality over cleverness, fast compilation over compile-time sophistication ('less is exponentially more'; the spec readable in an afternoon); the toolchain as the language — gofmt's mechanical uniformity, the package as compilation and encapsulation unit, visibility by capitalization (fmt.Println works because Println is capitalized; a lowercase JSON field is silently ignored), modules (go.mod, go.sum, Minimal Version Selection picking the oldest satisfying version so no dependency silently upgrades another, import paths instead of a central registry, init() and blank imports, unused variable/imports as compile errors); types and the zero value — byte/rune aliases, string as immutable byte sequence with rune-decoding range, the zero value as philosophy (unlocked sync.Mutex, empty bytes.Buffer, 'the zero value is useful'), := as shadowing hazard for err, nominal types (Celsius vs float64), type aliases, explicit conversions with no promotion, untyped constants and iota enums without exhaustiveness; composite types — arrays as values whose length is part of the type, the slice as a three-word header (pointer, len, cap) with append's geometric growth and must-use return value, the aliasing bug and three-index slice fix, nil slices behaving correctly, the Go 1.21 slices package; maps (comparable keys, comma-ok, read-from-nil OK / write-to-nil panics, deliberately randomized iteration order, unsafe concurrency with runtime fatal detection, sync.Map, Swiss tables since 1.24); structs as values with field-order padding, struct tags as reflection-read metadata, embedding as composition not inheritance (no virtual dispatch, no super); pointers without arithmetic, escape analysis and return &x safety, contiguous growing goroutine stacks; functions with multiple returns, named returns, variadics, closures capturing by reference with the pre-1.22 loop-variable bug fixed by per-iteration semantics in 1.22, defer's LIFO order and immediate argument evaluation, panic/recover culture (panics for programmer errors, not control flow; net/http's per-request recover); methods on any named type in-package, value vs pointer receivers and the all-or-nothing consistency rule, method values vs method expressions; interfaces as Go's center — implicit structural satisfaction, io.Reader's reach, 'accept interfaces, return structs', the two-word value (itab/eface) with boxing allocation cost, the typed-nil trap (return literal nil), method-set rules deciding which of T/*T satisfies, the empty interface/any, type assertions and switches, interface embedding and the var _ io.Reader assertion; errors as values — the error interface, sentinel errors (io.EOF), custom error types, wrapping with %w and errors.Is/As/Unwrap/Join, narrative context instead of stack traces, 'you dropped the error' as the canonical review comment; generics since 1.18 — type parameters, constraints as interfaces with type sets and tilde, comparable, inference, GC shape stenciling with dictionaries (not always as fast as hand-specialized), deliberate limits (no parameterized methods, no specialization), 'write code, not types', and range-over-function iterators (iter.Seq) since 1.23; concurrency as the distinctive core — CSP lineage and 'share memory by communicating', the G-M-P M:N scheduler (local run queues, work stealing, asynchronous preemption since 1.14, syscall handoff, the netpoller making blocking code cheap), channels (unbuffered rendezvous as synchronization, buffered decoupling, close semantics, nil-channel select disabling, directional types), select with random choice and default, context.Context as request-scoped cancellation threaded explicitly first-parameter, sync package (Mutex, RWMutex, WaitGroup, Once, Pool, atomic), channels-for-ownership vs mutexes-for-state, named patterns (worker pool, pipeline, fan-out/fan-in, semaphore, errgroup), the happens-before memory model with data races as undefined behavior and the race detector as non-negotiable; the runtime — statically linked two-megabyte hello-world, the non-generational non-compacting concurrent tri-color GC optimizing sub-millisecond pauses over throughput (GOGC, GOMEMLIMIT, write barriers, mark assists), fast compilation by non-transitive imports and no macros, GOOS/GOARCH cross-compilation, build constraints, cgo's costs, unsafe and reflect as escape hatches; testing culture — table-driven tests with subtests, benchmarks, examples, native fuzzing, external test packages, hand-written fakes over small interfaces; and the closing accounting: Go trades inheritance, exceptions, macros, implicit conversions and rich generics for a stranger's code readable at scale — learn the zero value, the slice header, the two-word interface, the receiver rules, the error idiom and channel semantics, and everything else follows from combining them.",
    concepts: [],
    practicePrompt: "Predict, then verify with the tools: for a function that returns a pointer to a local struct, run `go build -gcflags=-m` and check escape analysis's decision; write a two-goroutine program that shares a map and confirm the runtime's fatal concurrent-write error under `go test -race`; reproduce the typed-nil bug by returning a nil *MyError as error, then fix it with a literal nil. Nothing was executed here — run these on your own toolchain and report what you saw.",
    checkPrompt: "Without references: why Go looks the way it does (Google's constraints, the three values, 'less is exponentially more'); visibility by capitalization and why a lowercase JSON field is silently dropped; gofmt and package-as-encapsulation; modules, go.sum, and Minimal Version Selection's oldest-version rule; the zero value philosophy and 'useful zero value' examples; := shadowing of err; nominal types vs aliases and explicit conversion without promotion; untyped constants and iota enums; arrays vs the slice header (pointer/len/cap), append's return value and growth, aliasing and the three-index fix, nil slices; maps (comparable keys, comma-ok, nil-map asymmetry, randomized iteration, fatal concurrent writes, Swiss tables since 1.24); structs as values, field-order padding, struct tags, embedding as composition without virtual dispatch; pointers without arithmetic, escape analysis and return-&x safety, contiguous growing stacks; multi-return, named returns, variadics, closures by reference and the pre-1.22 loop-variable bug, defer's LIFO/immediate-evaluation/open-coding, panic/recover culture and net/http's per-request recover; value vs pointer receivers and the consistency rule, method values vs expressions; implicit interface satisfaction, io.Reader's reach, 'accept interfaces, return structs', the two-word representation and boxing cost, the typed-nil trap and its fix, method sets deciding T vs *T satisfaction, any, assertions/type switches, interface embedding, the var _ check; errors as values (sentinel, custom types, %w wrapping, errors.Is/As/Join, narrative context, 'you dropped the error'); generics (type parameters, constraints, type sets and tilde, comparable, inference, GC shape stenciling with dictionaries, no parameterized methods, 'write code, not types', iter.Seq since 1.23); concurrency (CSP, 'share memory by communicating', G-M-P scheduler with work stealing and async preemption, syscall handoff, netpoller, channel rendezvous semantics, close/nil-channel rules, directional types, select's random choice, context.Context as explicit first parameter, sync toolkit, ownership vs state, named patterns, happens-before, -race as non-negotiable); the runtime (static linking, sub-millisecond non-generational non-compacting GC, GOGC/GOMEMLIMIT, write barriers, mark assists, fast builds, GOOS/GOARCH, cgo's cost, unsafe/reflect); testing (table-driven, benchmarks, examples, fuzzing, external test packages, hand-written fakes); and what Go trades away and why.",
    tier: 1,
