    checkPrompt: "Without references: the design thesis (reading over writing, teams over individuals, tenth year over first week; the median-maintainer argument) and why the complexity lives in the runtime; packages and capitalization-visibility with internal/ directories; name-then-type declarations, zero values and useful-zero idioms; the blank identifier, iota (and why it's not a sum type), semicolon insertion, gofmt; nominal types vs aliases and the three relations (assignability/convertibility/comparability; incomparable slices/maps/functions; interface comparison panics); untyped constants with default types and the absence of runtime immutability; strings as byte headers with rune ranging; the slice header, append's aliasing and growth, the full slice expression, nil vs empty, retention leaks and slices.Clone; maps (nil asymmetry, comma-ok, randomized order, non-addressable elements, fatal concurrent writes, sync.Map, Swiss tables); structs as values with padding, struct{} as zero bytes, tags as unchecked strings, embedding without virtual dispatch; pointers without arithmetic and escape analysis; multiple returns, closures by reference, the pre-1.22 loop-variable fix, methods on named types, receiver choice and copylocks, method sets and auto-addressing; defer's LIFO/immediate evaluation/named returns/open-coding and the defer-in-loop leak; implicit interface satisfaction, 'bigger interface = weaker abstraction', 'accept interfaces, return structs', the two-word representation, the typed-nil trap, assertions and type switches; errors as values (sentinel/custom/Join/wrapping; lowercase style; handle-or-return); panic/recover rules and fatal errors; goroutines (2 KB stacks, costs) and G-M-P (handoff, netpoller, async preemption, GOMAXPROCS); channels (rendezvous semantics, close rules, nil-disabling, directional types), select's random choice; the memory model (happens-before list, seq-consistent atomics, races as UB, race detector costs); 'channels orchestrate; mutexes serialize' and the sync toolkit; context (first parameter, trees, defer cancel, cooperative cancellation, leaks and pprof); patterns (pipelines, fan-out/fan-in, errgroup, synctest); generics (type sets and tilde, constraint-only interfaces, inference, GC shape stenciling, no parameterized methods); the GC (tri-color, hybrid write barrier, mark assists, pacer, GOGC/GOMEMLIMIT, non-moving, Green Tea); escape analysis and the per-P allocator; modules (MVS, Semantic Import Versioning, checksum DB, GOPROXY); the test/vet/pprof/PGO/embed/build toolchain; cgo's costs and 'cgo is not Go'; reflection's three laws and costs; unsafe's uintptr rule and linkname; the compatibility promise with version gating; the proverbs and naming style; and the honest limits list.",
