      "Treating astrophage as manufactured fuel: it is farmed, not manufactured — given CO₂ and heat it self-replicates; that's why it is both the threat and the solution.",
      "Looking for an AI in the lineage: there is none — no HAL; the only other mind in the story is genuinely alien, a deliberate and increasingly rare choice."
